int register_usb_audio_device(struct usb_interface *intf, const struct usb_device_id *usb_id) {
    struct usb_device *udev;
    int err = 0;
    int card_index = -1;
    struct snd_card *card = NULL;

    udev = interface_to_usbdev(intf);
    if (!udev) {
        return -ENODEV;
    }

    if (quirk_present(udev)) {
        apply_boot_quirks(udev);
    }

    if (device_already_registered(udev)) {
        return 0;
    }

    card_index = find_available_card_slot();
    if (card_index < 0) {
        return -ENOSPC;
    }

    err = snd_card_new(&card, card_index, "USB Audio", 0, sizeof(struct snd_usb_audio));
    if (err < 0) {
        return err;
    }

    if (has_multiple_control_interfaces(udev)) {
        handle_multiple_interfaces(card, intf);
    }

    err = alsa_register_card(card);
    if (err < 0) {
        snd_card_free(card);
        return err;
    }

    return 0;
}

int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *dev = interface_to_usbdev(intf);
    int err = -ENODEV;
    int card_idx;

    if (!dev)
        return -EINVAL;

    if (dev->state != USB_STATE_CONFIGURED)
        return -ENODEV;

    if (quirk_has_boot_quirk(dev)) {
        err = quirk_apply_boot_quirk(dev);
        if (err < 0)
            return err;
    }

    if (dev->driver) {
        if (dev->driver == &snd_usb_audio_driver)
            return -EBUSY;
    }

    card_idx = find_first_zero_bit(card_present, SNDRV_CARDS);
    if (card_idx < 0)
        return -ENOSPC;

    struct snd_card *card = snd_card_new(card_idx, "USB Audio", 0, 0);
    if (!card)
        return -ENOMEM;

    err = snd_usb_card_register(card, intf, usb_id);
    if (err < 0) {
        snd_card_free(card);
        return err;
    }

    dev->driver_data = card;
    return 0;
}

int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *dev = interface_to_usbdev(intf);
    int err;

    if (dev->quirks)
        apply_boot_quirks(dev);

    if (device_is_registered(dev))
        return 0;

    err = find_available_slot();
    if (err < 0)
        return err;

    if (has_multiple_control_interfaces(dev))
        handle_multiple_control_interfaces(dev);

    err = register_with_alsa(dev);
    if (err < 0) {
        cleanup_resources(dev);
        return err;
    }

    return 0;
}

int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *dev = interface_to_usbdev(intf);
    int err;

    if (!dev) {
        return -ENODEV;
    }

    err = snd_usb_apply_boot_quirk(dev, intf, usb_id);
    if (err < 0) {
        return err;
    }

    if (snd_usb_is_registered(dev)) {
        return 0;
    }

    err = snd_card_new(&intf->dev, SNDRV_DEFAULT_IDX1, SNDRV_DEFAULT_STR1,
                       THIS_MODULE, 0, NULL);
    if (err < 0) {
        return err;
    }

    err = snd_usb_create_card(intf, dev, usb_id);
    if (err < 0) {
        snd_card_free(dev->card);
        return err;
    }

    err = snd_card_register(dev->card, NULL);
    if (err < 0) {
        snd_card_free(dev->card);
        return err;
    }

    return 0;
}

int probe_usb_audio_device(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *usb_dev = interface_to_usbdev(intf);
    struct snd_card *card = NULL;
    int err;

    if (!usb_dev)
        return -EINVAL;

    /* Check for any device quirks or special handling */
    if (usb_id) {
        if (usb_id->driver_info & USB_DEVICE_QUIRK_FLAG) {
            err = apply_boot_quirks(usb_dev);
            if (err < 0)
                return err;
        }
    }

    /* Check if the device is already registered */
    if (snd_usb_find_device(usb_dev)) {
        return -EEXIST;
    }

    /* Allocate a new sound card instance */
    err = snd_card_new(&card);
    if (err < 0) {
        return err;
    }

    /* Handle devices with multiple control interfaces */
    if (usb_dev->actconfig->interface[1].desc.bInterfaceClass == USB_CLASS_HID) {
        err = handle_control_interface(intf, card);
        if (err < 0) {
            snd_card_free(card);
            return err;
        }
    }

    /* Register the card with ALSA */
    err = snd_card_register(card);
    if (err < 0) {
        snd_card_free(card);
        return err;
    }

    usb_set_intfdata(intf, card);

    return 0;
}
